SELECT
  COALESCE((SELECT SUM(Amount * Price) FROM transactions_1k WHERE CustomerID = 38508 AND GasStationID IS NOT NULL), 0) AS gas_spent,
  COALESCE((SELECT Consumption FROM yearmonth WHERE CustomerID = 38508 AND Date = '201201'), 0) AS jan2012_spent;

SELECT CASE WHEN COUNT(*)=0 THEN 0.0 ELSE 100.0 * SUM(CASE WHEN LOWER(colour.colour) LIKE '%blue%' THEN 1 ELSE 0 END) / COUNT(*) END
FROM superhero
LEFT JOIN colour ON superhero.eye_colour_id = colour.id;

SELECT CASE WHEN total = 0 THEN 0.0 ELSE (elder * 100.0) / total END
FROM (
  SELECT
    (SELECT COUNT(*) FROM posts WHERE Score > 5) AS total,
    (SELECT COUNT(*) FROM posts JOIN users ON posts.OwnerUserId = users.Id WHERE posts.Score > 5 AND users.Age > 65) AS elder
);

SELECT CASE WHEN COUNT(*)=0 THEN 0.0 ELSE 100.0 * SUM(CASE WHEN Score>50 THEN 1 ELSE 0 END) / COUNT(*) END AS Percentage
FROM posts
WHERE OwnerUserId IN (
  SELECT Id FROM users WHERE Reputation = (SELECT MAX(Reputation) FROM users)
);

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT CASE WHEN d.denom = 0 THEN 0.0 ELSE 100.0 * n.num / d.denom END AS percentage
FROM (SELECT COUNT(DISTINCT uuid) AS denom FROM cards WHERE power IS NULL OR power = '*') d
CROSS JOIN (SELECT COUNT(DISTINCT cards.uuid) AS num FROM cards JOIN foreign_data ON cards.uuid = foreign_data.uuid WHERE (cards.power IS NULL OR cards.power = '*') AND foreign_data.language = 'French') n;

SELECT 100.0 * SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM atom
WHERE molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '=');

SELECT CASE WHEN COUNT(*) = 0 THEN 0.0 ELSE 100.0 * SUM(CASE WHEN atom.element = 'cl' THEN 1 ELSE 0 END) / COUNT(*) END AS percentage
FROM molecule JOIN atom ON molecule.molecule_id = atom.molecule_id
WHERE molecule.label = '+';
